export const fmtPct = (v, digits = 0) =>
  v === null || v === undefined ? '—' : `${(v * 100).toFixed(digits)}%`;

export const fmtNum = (v, digits = 1) =>
  v === null || v === undefined ? '—' : Number(v).toFixed(digits);

export const fmtCI = (ci, digits = 0) =>
  !ci || ci[0] === null || ci[1] === null
    ? '—'
    : `${(ci[0] * 100).toFixed(digits)}–${(ci[1] * 100).toFixed(digits)}%`;

export const fmtCIRaw = (ci, digits = 1) =>
  !ci || ci[0] === null || ci[1] === null
    ? '—'
    : `${Number(ci[0]).toFixed(digits)}–${Number(ci[1]).toFixed(digits)}`;
